"""Build the ThorGor v57 K2 patch from a user-supplied HoN 3.2.7.1 DLL.

No game binary is distributed with this repository. The source and output
hashes are intentionally strict so this patch cannot be applied to another
client version by accident.
"""

from __future__ import annotations

import hashlib
import sys
from pathlib import Path


SOURCE_SHA256 = "8929AE8993AF41AE9F63BEE43DAB27402205621CFFC57F8ACC8DB0C4FB95FAE9"
OUTPUT_SHA256 = "6F5FC1F7BF4E01CDEB0360A6F703299F5422F2C06A104FADCB24FD96A546B8DF"

# Offset and replacement bytes. These reproduce the independently developed
# v39-v57 interoperability changes without embedding or distributing k2.dll.
PATCHES = (
    (0x2B630C, "b96f04000090"),
    (0x2B6BC3, "b86f040000"),
    (0x2B8690, "b96f04000090"),
    (0x2F1A20, "e91bb941"),
    (0x2F1A80, "e9ebb841"),
    (0x2F1AB0, "e9ebb841000085c074118b40083b4424047508b801000000c2040033c0c20400e9fbb841"),
    (0x2F1B40, "e9abb84100"),
    (0x2F2E83, "9090909090"),
    (0x2F4990, "e9ab8a4100"),
    (0x2F49C0, "e9cb8a4100"),
    (0x2F5415, "eb"),
    (0x2F5978, "909090909090807def000f859a0200008b7d08c687bb02000000eb"),
    (0x2F59C8, "34"),
    (0x2F5AF9, "75088d96800100008b0285c074088d9030840000ebf2c7833084000000000000891a8d85dcfeffff505390909090909090909090909090909090e858320000807e04008b868001000074098b4e5c53"),
    (0x2F5DBA, "575056e80e77410089c78b5c2414eb3e9090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090"),
    (0x2F60C4, "56e8a6744100eb599090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090c686d002000001909090909090"),
    (0x2F61CC, "686f040000909090"),
    (0x2F6271, "8e850000009090"),
    (0x2F680F, "57e81b6d4100eb6d90909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090909090"),
    (0x2F6D02, "57e898684100eb179090909090909090909090909090909090909090909090"),
    (0x5E9F1A, "b4d373"),
    (0x70D340, ""),
    (0x74E518, "3100320037002e0030002e0030002e003100000000000000000000"),
    (0x7584FC, "2000200020002000200020"),
    (0x758A04, "2000200020002000200020"),
)


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest().upper()


def build(source: Path, target: Path) -> str:
    data = bytearray(source.read_bytes())
    digest = sha256(data)
    if digest != SOURCE_SHA256:
        raise ValueError(f"unexpected source hash {digest}")
    for offset, replacement_hex in PATCHES:
        replacement = bytes.fromhex(replacement_hex)
        data[offset : offset + len(replacement)] = replacement
    result = sha256(data)
    if result != OUTPUT_SHA256:
        raise ValueError(f"unexpected output hash {result}")
    target.write_bytes(data)
    return result


def main(argv: list[str]) -> int:
    if len(argv) != 3:
        print("usage: build_k2_v57.py SOURCE_K2_DLL OUTPUT_K2_DLL", file=sys.stderr)
        return 2
    try:
        print(build(Path(argv[1]), Path(argv[2])))
    except (OSError, ValueError) as exc:
        print(f"patch failed: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
